import{_ as r,o as a,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"اینکر سے پہلے کا دور","description":"","frontmatter":{},"headers":[],"relativePath":"ur/71-前锚点时代.md","filePath":"ur/71-前锚点时代.md","lastUpdated":null}'),d={name:"ur/71-前锚点时代.md"};function i(e,t,n,s,h,u){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="اینکر-سے-پہلے-کا-دور" tabindex="-1">اینکر سے پہلے کا دور <a class="header-anchor" href="#اینکر-سے-پہلے-کا-دور" aria-label="Permalink to &quot;اینکر سے پہلے کا دور&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>71</td></tr><tr><td>ماڈیول</td><td>تاریخی عہد اور اہم واقعات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>اینکر سے پہلے کا دور، لوٹ مار کا نظام، تہذیب کی خرابی، تاریک دور، قانون کی بے قاعدگی</td></tr></tbody></table><h2 id="_1-اینکر-سے-پہلے-کے-دور-کی-بنیادی-خصوصیات" tabindex="-1">1. اینکر سے پہلے کے دور کی بنیادی خصوصیات <a class="header-anchor" href="#_1-اینکر-سے-پہلے-کے-دور-کی-بنیادی-خصوصیات" aria-label="Permalink to &quot;1. اینکر سے پہلے کے دور کی بنیادی خصوصیات&quot;">​</a></h2><p>اینکر سے پہلے کا دور ہینگیوان-ژو کی تاریخ میں سب سے طویل اور سب سے تاریک دور ہے۔ اس دور میں، کائنات میں کوئی متحد اینکر میکانزم موجود نہیں تھا، بنیادی قوانین قدرتی طور پر پھیلے ہوئے تھے، اور توانائی اور وسائل کی تقسیم مکمل طور پر &quot;طاقتور اسے حاصل کرتا ہے&quot; کے جنگل کے قانون پر مبنی تھی۔ لوٹ مار کی سادھنا کا نظام اس دور کا مطلق مسلط تھا؛ سادھنا کے طریقے چند طاقتور افراد اور فرقوں کے ہاتھ میں تھے، اور نچلی سطح کے عام جانداروں کے پاس رسمی ارتقاء کا راستہ تقریباً نہیں تھا۔</p><p>اینکر سے پہلے کے دور کی بنیادی خصوصیات کو &quot;پانچ عدم&quot; کے طور پر خلاصہ کیا جا سکتا ہے:</p><ul><li><strong>اینکر نہیں</strong>: مستحکم قانون کے اینکر نہیں تھے، توانائی کا بہاؤ بے قاعدہ تھا، اور تلواروں کی دیواریں کمزور تھیں</li><li><strong>نظم و ضبط نہیں</strong>: کوئی متحد تہذیب کا نظام نہیں تھا، تلواروں کے درمیان جنگیں جاری تھیں، اور نسلوں کا خاتمہ اکثر ہوتا تھا</li><li><strong>راستہ نہیں</strong>: تلواروں کے درمیان مواصلاتی اور نقل و حمل کی ٹیکنالوجی نہیں تھی، اور تلواریں بنیادی طور پر ایک دوسرے سے الگ تھلگ تھیں</li><li><strong>یقین دہانی نہیں</strong>: تعلیم، صحت، رہائش جیسے عوامی یقین دہانی کے نظام نہیں تھے، اور زندگی کا وجود مکمل طور پر انفرادی طاقت پر منحصر تھا</li><li><strong>امید نہیں</strong>: نچلی سطح کے جانداروں کے ارتقاء کے راستے مکمل طور پر بند تھے، اور سماجی درجہ بندی انتہائی حد تک پہنچ گئی تھی</li></ul><h2 id="_2-لوٹ-مار-کی-سادھنا-کے-نظام-کا-طریقہ-کار" tabindex="-1">2. لوٹ مار کی سادھنا کے نظام کا طریقہ کار <a class="header-anchor" href="#_2-لوٹ-مار-کی-سادھنا-کے-نظام-کا-طریقہ-کار" aria-label="Permalink to &quot;2. لوٹ مار کی سادھنا کے نظام کا طریقہ کار&quot;">​</a></h2><p>اینکر سے پہلے کے دور کی سادھنا کا نظام لوٹ مار کو بنیادی طریقہ کار کے طور پر اپناتا تھا۔ اس کی بنیادی منطق یہ تھی: کائنات کی بنیادی توانائی محدود ہے، اور فرد کا ارتقاء لازماً دوسروں کی توانائی کی قیمت پر ہوتا ہے۔ طاقتور لوگ کمزوروں کی توانائی، قسمت اور یہاں تک کہ بنیادی ذات کو کھا کر اپنی بلندی حاصل کرتے تھے، جبکہ کمزور لوگ طاقتوروں کے &quot;سادھنا کے وسائل&quot; بن جاتے تھے۔</p><p>لوٹ مار کے نظام کی عام شکلیں درج ذیل ہیں:</p><table tabindex="0"><thead><tr><th>لوٹ مار کی قسم</th><th>طریقہ کار</th><th>کائنات کو نقصان</th></tr></thead><tbody><tr><td>توانائی کی لوٹ مار</td><td>دوسرے جانداروں کی سادھنا توانائی براہ راست چوسنا</td><td>فرد کی موت یا سادھنا کا مکمل ضیاع</td></tr><tr><td>قسمت کی لوٹ مار</td><td>جادو یا رسومات کے ذریعے دوسروں کی قسمت اور مواقع چھیننا</td><td>وجہ و نتیجہ کا توازن خراب، تلوار کی سطح کے آفات کا باعث بنتا ہے</td></tr><tr><td>بنیادی ذات کی لوٹ مار</td><td>دوسرے جانداروں کے بنیادی قانون کے ٹکڑوں کو کھا جانا</td><td>ارتقاء کی صلاحیت کا ناقابل واپسی نقصان</td></tr><tr><td>تلوار کی لوٹ مار</td><td>طاقتور لوگ پوری تلوار کو فتح کرتے ہیں اور تلوار کے جانداروں کو سادھنا کے وسائل کے طور پر استعمال کرتے ہیں</td><td>تہذیب کا خاتمہ اور تلوار کا صحرا بن جانا</td></tr><tr><td>قانون کی لوٹ مار</td><td>کسی تلوار کے بنیادی قانون کے کنٹرول کو زبردستی چھیننا</td><td>قانون کے نیٹ ورک کو نقصان، خلائی تباہی کا باعث بنتا ہے</td></tr></tbody></table><p>لوٹ مار کا نظام مختصر مدت میں چند انتہائی طاقتور افراد پیدا کر سکتا ہے، لیکن طویل مدت میں یہ کائنات کی ارتقائی صلاحیت کو مسلسل خرچ کرتا ہے، جس کے نتیجے میں کائنات کی عمومی اینٹروپی میں تیزی سے اضافہ ہوتا ہے اور تہذیب کی خرابی اکثر ہوتی ہے۔</p><h2 id="_3-تہذیب-کی-خرابی-اور-چکراتی-تباہی" tabindex="-1">3. تہذیب کی خرابی اور چکراتی تباہی <a class="header-anchor" href="#_3-تہذیب-کی-خرابی-اور-چکراتی-تباہی" aria-label="Permalink to &quot;3. تہذیب کی خرابی اور چکراتی تباہی&quot;">​</a></h2><p>اینکر سے پہلے کے دور کی سب سے نمایاں تاریخی واقعہ &quot;تہذیب کی خرابی&quot; ہے۔ لوٹ مار کے نظام کی موروثی تضاد کی وجہ سے، ہر وہ تہذیب جو کبھی روشن تھی آخر کار خود تباہی کی طرف بڑھتی ہے:</p><ol><li><strong>عروج کا دور</strong>: ایک نسل یا فرقہ لوٹ مار کے ذریعے تیزی سے عروج پر پہنچتا ہے اور ایک طاقتور تہذیب قائم کرتا ہے</li><li><strong>چوٹی کا دور</strong>: تہذیب طاقت کی چوٹی پر پہنچ جاتی ہے، اندرونی مزاحمت کو دباتی ہے، اور بیرونی طور پر لوٹ مار کے لیے پھیلتی ہے</li><li><strong>اندرونی جنگ کا دور</strong>: تہذیب کے اندر طاقتور لوگ محدود وسائل کے لیے ایک دوسرے سے لڑتے ہیں، اپنی طاقت خرچ کرتے ہیں</li><li><strong>تباہی کا دور</strong>: اندرونی جنگ کے نتیجے میں تہذیب کی طاقت میں زبردست کمی واقع ہوتی ہے، اور بیرونی لوٹ مار کرنے والے موقع کا فائدہ اٹھاتے ہیں، جس کے نتیجے میں تہذیب کا خاتمہ ہو جاتا ہے</li><li><strong>خرابی کا دور</strong>: تہذیب کے خاتمے کے بعد، اس کا زیادہ تر علم اور ٹیکنالوجی ضائع ہو جاتی ہے، اور اگلی تہذیب کو صفر سے شروع کرنا پڑتا ہے</li></ol><p>&quot;عروج—چوٹی—اندرونی جنگ—تباہی—خرابی&quot; کا یہ چکر اینکر سے پہلے کے دور میں ان گنت بار دہرایا گیا ہے۔ ہر چکر نے کائنات کی بنیادی ذات کی بڑی مقدار کو خرچ کیا ہے، جس کے نتیجے میں کائنات کی عمومی ارتقائی سطح طویل عرصے سے جمود کا شکار ہے یا یہاں تک کہ پیچھے ہٹ گئی ہے۔</p><h2 id="_4-اینکر-سے-پہلے-کے-دور-کے-اختتامی-علامات" tabindex="-1">4. اینکر سے پہلے کے دور کے اختتامی علامات <a class="header-anchor" href="#_4-اینکر-سے-پہلے-کے-دور-کے-اختتامی-علامات" aria-label="Permalink to &quot;4. اینکر سے پہلے کے دور کے اختتامی علامات&quot;">​</a></h2><p>اینکر سے پہلے کے دور کے اختتام پر، کائنات میں تبدیلی کا اشارہ دینے والی کئی علامات نمودار ہوئیں:</p><ul><li><strong>قانون کی بے قاعدگی میں اضافہ</strong>: طویل مدتی لوٹ مار کے نتیجے میں قانون کے نیٹ ورک کو شدید نقصان پہنچا، خلائی تباہی کے واقعات اکثر ہونے لگے، اور تلواروں کی دیواریں پتلی ہو گئیں</li><li><strong>زندگی کی صلاحیت کا خاتمہ</strong>: لوٹ مار کے قابل بنیادی توانائی تیزی سے کم ہو رہی تھی، اور طاقتور لوگوں کے درمیان وسائل کی مسابقت شدید ہو گئی</li><li><strong>لوٹ مار مخالف فکر کی جڑیں</strong>: کچھ دانشور لوگ لوٹ مار کے نظام کی بنیادی خامیوں پر غور کرنے لگے اور باہمی ارتقاء کے ابتدائی تصورات پیش کیے</li><li><strong>تلواروں کے درمیان رابطے میں اضافہ</strong>: تلواروں کی دیواریں پتلی ہونے کے نتیجے میں مختلف تلواروں کے درمیان رابطے میں اضافہ ہوا، اور تلواروں کے درمیان خیالات کا تبادلہ ممکن ہوا</li><li><strong>پہلی نسل کے اینکر امیدواروں کا ظہور</strong>: کائنات کے کچھ کونوں میں، ایسے خاص جاندار نمودار ہوئے جو قانون کے نیٹ ورک کے ساتھ قدرتی طور پر گونج پیدا کر سکتے تھے؛ وہ مستقبل کے پہلی نسل کے اینکر بیدار ہونے والوں کے پیش رو تھے</li></ul><p>یہ علامات اس بات کی نشاندہی کرتی ہیں کہ لوٹ مار کا نظام اپنے اختتام کو پہنچ گیا ہے، اور کائنات ایک بالکل نئی تہذیب کی شکل کا مطالبہ کر رہی ہے۔</p><h2 id="_5-اینکر-سے-پہلے-کے-دور-کی-تاریخی-ورثہ" tabindex="-1">5. اینکر سے پہلے کے دور کی تاریخی ورثہ <a class="header-anchor" href="#_5-اینکر-سے-پہلے-کے-دور-کی-تاریخی-ورثہ" aria-label="Permalink to &quot;5. اینکر سے پہلے کے دور کی تاریخی ورثہ&quot;">​</a></h2><p>اینکر سے پہلے کا دور اگرچہ تاریک تھا، لیکن یہ مکمل طور پر بے قیمت نہیں تھا۔ اس نے بعد میں آنے والی اینکر سمبیوسس تہذیب کے لیے اہم تاریخی ورثہ چھوڑا:</p><ul><li><strong>سبق کی ورثہ</strong>: لوٹ مار کے نظام کی بار بار ناکامی نے سمبیوسس تہذیب کے لیے سب سے گہرا منفی سبق فراہم کیا، جو ثابت کرتا ہے کہ لوٹ مار کا راستہ کسی کام کا نہیں</li><li><strong>علم کی ورثہ</strong>: اگرچہ تہذیب کی خرابی میں بہت سارا علم ضائع ہو گیا، لیکن کچھ سادھنا کے طریقے اور قانون کی سمجھ مختلف طریقوں سے بچی رہی، جو تین سو بنیادی سادھنا کے نظام کے مواد کا ذریعہ بنی</li><li><strong>زندگی کی ورثہ</strong>: طویل تاریک دور میں بچ جانے والی مختلف شکلوں کی زندگی نے مستقبل کی تمام نسلوں کی سمبیوسس کی نسلی بنیاد بنائی</li><li><strong>ارادہ کی ورثہ</strong>: نچلی سطح کے جانداروں کی انصاف اور امید کے لیے مستقل خواہش اینکر کی بیداری کی سب سے بنیادی روحانی طاقت تھی</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>اینکر سے پہلے کا دور ہینگیوان-ژو کی تاریخ کی &quot;اندھیرے کی پوری رات&quot; ہے۔ اس کی طوالت اور تاریکی، بالکل برعکس اینکر سمبیوسس تہذیب کی پیدائش کی قدر اور لازمی ہونے کو ظاہر کرتی ہے۔ اینکر سے پہلے کے دور کو سمجھنا، سمبیوسس تہذیب کی &quot;لوٹ مار کی مخالفت، سمبیوسس کی وکالت&quot; کی اس بنیادی موقف کی تاریخی جڑوں کو سمجھنا ہے — یہ کوئی مجرد اخلاقی واعظ نہیں، بلکہ ان گنت تہذیبوں کی تباہی کے بدلے میں حاصل شدہ خون و اشک کا سبق ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>70-عہدوں کی تقسیم کا عمومی جدول</li><li>72-اینکر کی بیداری کا عہد</li><li>04-لوٹ مار مخالفیت کا بنیادی پروگرام</li></ul>',26)])])}const p=r(d,[["render",i]]);export{_ as __pageData,p as default};
